// Walk rope chunks without copying/scanning the whole document per key.
// Keep exact byte/UTF-16 IME replacement APIs unchanged.
fn adjacent_grapheme_boundary(&self, offset: usize, forward: bool) -> usize {
    let offset = self.text.clip_offset(offset, Bias::Left);
    let len = self.text.len();
    if (!forward && offset == 0) || (forward && offset == len) {
        return offset;
    }
    let mut cursor = GraphemeCursor::new(offset, len, true);
    let (mut chunk, mut start) = self.text.chunk(if forward { offset } else { offset - 1 });
    loop {
        let result = if forward {
            cursor.next_boundary(chunk, start)
        } else {
            cursor.prev_boundary(chunk, start)
        };
        match result {
            Ok(Some(boundary)) => return boundary,
            Ok(None) => return if forward { len } else { 0 },
            Err(GraphemeIncomplete::PreContext(end)) => {
                let (context, context_start) = self.text.chunk(end - 1);
                cursor.provide_context(&context[..end - context_start], context_start);
            }
            Err(GraphemeIncomplete::PrevChunk) => {
                (chunk, start) = self.text.chunk(start - 1);
            }
            Err(GraphemeIncomplete::NextChunk) => {
                (chunk, start) = self.text.chunk(start + chunk.len());
            }
            Err(GraphemeIncomplete::InvalidOffset) => {
                unreachable!("grapheme cursor and rope chunks must share byte offsets");
            }
        }
    }
}

