    let mut owners = Vec::new();
    let mut layouts = HashMap::new();
    let last = std::cell::Cell::new(usize::MAX);
    for _ in 0..RETAINED_SWEEP_AT {
        let owner = Arc::new(Mutex::new(InlineState::default()));
        layouts.insert(state_key(&owner), entry(&owner));
        owners.push(owner);
    }
    let epoch = RETAINED_STATE_DROPS.load(std::sync::atomic::Ordering::Acquire);
    assert!(sweep_retained_layouts(&mut layouts, epoch, &last));
    for _ in 0..128 {
        assert!(!sweep_retained_layouts(&mut layouts, epoch, &last));
    }
    assert_eq!(layouts.len(), RETAINED_SWEEP_AT);
    let dead = owners.pop().unwrap();
    let dead_key = state_key(&dead);
    std::thread::spawn(move || drop(dead)).join().unwrap();
    let changed = RETAINED_STATE_DROPS.load(std::sync::atomic::Ordering::Acquire);
    assert_ne!(epoch, changed);
    assert!(sweep_retained_layouts(&mut layouts, changed, &last));
    assert!(!layouts.contains_key(&dead_key));
    assert_eq!(layouts.len(), RETAINED_SWEEP_AT - 1);
    assert!(owners.iter().all(|owner| layouts.contains_key(&state_key(owner))));
