    let next = RETAINED_STATE_DROPS.load(std::sync::atomic::Ordering::Acquire);
    assert!(!sweep_retained_layouts(&mut layouts, next, &last));
    assert!(layouts.contains_key(&another_key));
    let owner = Arc::new(Mutex::new(InlineState::default()));
    layouts.insert(state_key(&owner), entry(&owner));
    assert!(sweep_retained_layouts(&mut layouts, next, &last));
    assert!(!layouts.contains_key(&another_key));

